import {LevelRun,validateLevel} from './level.mjs';
import {setupFullscreen} from './fullscreen.mjs';
import {SceneRun} from './scene-run.mjs';
import {validateScene} from './scene.mjs';
import {request} from './cloud-ui.mjs';
import {validateGameAsset,assetTypes,itemLabel} from './assets.mjs';
import {createGameImages} from './game-animations.mjs';
import {effects,validateDungeon} from './core.mjs';
import {Run} from './engine.mjs';
import {render,drawMap} from './render.mjs';
import {dungeon as testDungeon} from './dungeon.mjs';
let dungeon=testDungeon,selectionError=false,asset=null,assetImage=null,assetError=null,scene=null,level=null;
const assetId=new URLSearchParams(location.search).get('asset');
if(assetId){try{asset=validateGameAsset(await request(`/api/designer/sprites/${encodeURIComponent(assetId)}`));assetImage=createGameImages([asset])}catch(e){assetError=e.message;}}
if(new URLSearchParams(location.search).get('dungeon')==='selected'){
 try{const saved=localStorage.getItem('nocturne:selected-dungeon');if(!saved||saved.length>100000)throw Error();dungeon=validateDungeon(JSON.parse(saved))}catch{selectionError=true}
}
const roomId=new URLSearchParams(location.search).get('room');
if(roomId){try{const saved=await request(`/api/rooms/${encodeURIComponent(roomId)}`);scene={...saved,...validateScene(saved.plan,saved.assets)};asset=null;assetImage=createGameImages(scene.assets)}catch(e){assetError=e.message;}}
const levelId=new URLSearchParams(location.search).get('level');
if(levelId){try{level=validateLevel(await request(`/api/levels/${encodeURIComponent(levelId)}`));scene=null;asset=null;assetImage=createGameImages([...new Map(level.rooms.flatMap(r=>r.assets).map(a=>[a.id,a])).values()]);}catch(e){assetError=e.message;}}
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d'),map=$('#minimap').getContext('2d');
let run,keys=new Set(),touch={x:0,y:0},pointer={x:480,y:300,down:false},sound=false,audio,last=performance.now(),toastTimer;
const atlas=new Image();atlas.src='sprites.png';
function beep(freq=300,volume=.02,duration=.08){if(!sound)return;try{audio??=new AudioContext();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(freq,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(freq*.55,audio.currentTime+duration);gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain).connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function showOverlay(kicker,title,copy,button){$('#overlay-kicker').textContent=kicker;$('#overlay-title').textContent=title;$('#overlay-copy').textContent=copy;$('#start').textContent=button;$('#overlay').hidden=false}
const formatTime=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;
function event(type,data){if(type==='shoot')beep(540,.015,.055);if(type==='hit')beep(170,.02,.05);if(type==='hurt')beep(85,.06,.2);if(type==='clear'){beep(680,.045,.25);toast('Salle purifiée · Les portes s’ouvrent');updateHUD()}if(type==='room'){toast(data);updateHUD()}if(type==='message')toast(data);if(type==='asset-item'){beep(850,.06,.35);toast(`${data.name} · ${data.label}`);updateHUD()}if(type==='relic'){beep(850,.06,.35);toast(`${data.name} · ${effects[data.effect].label}`);updateHUD()}if(type==='dead')showOverlay('EXPÉDITION TERMINÉE','La crypte vous garde.',`${run.kills} ennemis vaincus · ${formatTime(run.elapsed)} · Le même donjon vous attend.`,'Tenter une nouvelle descente');if(type==='won')showOverlay(scene?'SALLE TERMINÉE':'LE GARDIEN EST TOMBÉ',scene?'La voie est libre.':'Vous verrez l’aube.',`${run.kills} ennemis vaincus · ${run.inventory.length} reliques · ${formatTime(run.elapsed)}`,'Rejouer ce donjon')}
function reset(start=false){keys.clear();touch={x:0,y:0};pointer.down=false;run=level?new LevelRun(level,event):scene?new SceneRun(scene,event):new Run(dungeon,event,asset);if(asset?.gameplay.type==='boss')run.enter(6);updateHUD();if(start){run.start();$('#overlay').hidden=true;canvas.focus()}else if(level)showOverlay('NIVEAU COMPLET',level.title,`${level.rooms.length} salles à explorer. Élimine les ennemis, récupère les bonus et franchis chaque sortie jusqu’au boss.`,'Jouer le niveau');else if(scene)showOverlay('SALLE PERSONNALISÉE',scene.plan.title,'Élimine les ennemis, ramasse les récompenses puis rejoins la sortie à droite.','Jouer la salle');else if(asset)showOverlay('TEST DU SPRITE',asset.sprite.name,assetTypes[asset.gameplay.type].hint,'Démarrer le test');else showOverlay('PREMIÈRE EXPÉDITION','La nuit recommence.','Sept salles. Trois reliques. Un gardien à faire taire.','Entrer dans la crypte')}
function updateHUD(){if(!run)return;
 $('#dungeon-title').textContent=level?level.title:scene?scene.plan.title:asset?asset.sprite.name:dungeon.blueprint.title;
 const generated=dungeon.source.startsWith('ollama-cloud:');
 $('#source-badge').textContent=level?'Niveau Ollama':scene?'Salle personnalisée':asset?assetTypes[asset.gameplay.type].label:generated?'Ollama Cloud':'Donjon fixe';
 $('#dungeon-kicker').textContent=level?'EXPÉDITION CRÉÉE PAR L’IA':scene?'ATELIER DE SALLES':asset?'TEST D’UN SPRITE':generated?'EXPÉDITION GÉNÉRÉE':'LE DONJON DE TEST';
 const rules={generous:['La crypte vous épargne.','Terminer une salle de combat vous rend un cœur.'],swift:['Légers comme l’ombre.','Votre vitesse de déplacement est augmentée de 12 %.'],fierce:['La nuit aiguise les dents.','Vos tirs infligent 15 % de dégâts supplémentaires.']};
 $('#rule-title').textContent=rules[dungeon.blueprint.rule][0];$('#rule-copy').textContent=rules[dungeon.blueprint.rule][1];
 $('#dungeon-note').textContent=generated?`Donjon créé le ${dungeon.date}.`:'Un donjon fixe pour découvrir le jeu.';
 if(asset){$('#rule-title').textContent='Fiche de jeu active';$('#rule-copy').textContent=assetTypes[asset.gameplay.type].hint;$('#dungeon-note').textContent=asset.gameplay.type==='item'?itemLabel(asset.gameplay.stats):Object.entries(asset.gameplay.stats).map(([key,value])=>`${assetTypes[asset.gameplay.type].fields[key].label} : ${typeof value==='boolean'?(value?'oui':'non'):assetTypes[asset.gameplay.type].fields[key].options?.[value]??value}`).join(' · ');}
 if(level){$('#rule-title').textContent='Atteindre la dernière salle';$('#rule-copy').textContent='Élimine les ennemis et ramasse les objets pour ouvrir chaque sortie.';$('#dungeon-note').textContent='Ta vie, tes bonus et ton équipement sont conservés entre les salles.';}
 if(scene){$('#rule-title').textContent='Libérer la salle';$('#rule-copy').textContent='Élimine les ennemis, récupère les objets puis rejoins la sortie à droite.';$('#dungeon-note').textContent='Les sprites et statistiques sont ceux de la sauvegarde de cette salle.';}
 $('#progress').textContent=`${run.rooms.filter(r=>r.visited).length} / ${run.rooms.length}`;$('#relic-count').textContent=`${run.inventory.length} / ${level?run.totalItems:scene?run.sceneItems.length:asset?.gameplay.type==='item'?4:3}`;const inventory=$('#inventory');inventory.replaceChildren();if(!run.inventory.length){const p=document.createElement('p');p.className='muted empty';p.textContent='La crypte garde encore ses secrets.';inventory.append(p)}for(const item of run.inventory){const row=document.createElement('div');row.className='relic';const icon=document.createElement('span');icon.className='relic-icon';icon.textContent=effects[item.effect]?.icon??'♥';const details=document.createElement('div'),name=document.createElement('strong'),desc=document.createElement('p');name.textContent=item.name;desc.textContent=item.label??effects[item.effect]?.label??'';details.append(name,desc);row.append(icon,details);inventory.append(row)}drawMap(map,run)}
let lastFullscreenExit=-Infinity;
const fullscreen=setupFullscreen({surface:$('#play-surface'),space:$('#arena-space'),viewport:$('#arena-viewport'),canvas,button:$('#fullscreen'),onError:toast,onExit:()=>{lastFullscreenExit=performance.now();if(run?.state==='playing')pause();}});
window.addEventListener('pagehide',()=>fullscreen.destroy(),{once:true});
$('#pause-game').onclick=()=>pause();
const back=$('#back-to-workshop');if(levelId){back.href='/generator.html';back.textContent='Retour aux donjons';}else if(roomId){back.href='/rooms.html';back.textContent='Retour aux salles';}else if(assetId){back.href='/designer.html';back.textContent='Retour aux sprites';}else if(new URLSearchParams(location.search).get('dungeon')==='selected'){back.textContent='Retour aux donjons';}
$('#back-to-test').hidden=!levelId&&!roomId&&!assetId&&new URLSearchParams(location.search).get('dungeon')!=='selected';
$('#start').onclick=()=>{if(run.state==='paused'){run.pause();$('#overlay').hidden=true;canvas.focus()}else if(run.state==='ready'){run.start();$('#overlay').hidden=true;canvas.focus();toast(scene?'Élimine les ennemis puis ramasse les récompenses et rejoins la sortie.':asset?assetTypes[asset.gameplay.type].hint:'Rejoignez la porte éclairée. Flèches ou clic maintenu pour tirer.')}else reset(true)};
$('#restart').onclick=()=>reset(true);
function pause(){if(!run)return;if(run.state==='playing'){run.pause();keys.clear();pointer.down=false;showOverlay('LA NUIT PEUT ATTENDRE','Une pause dans l’ombre.','Votre expédition est conservée.','Reprendre')}else if(run.state==='paused'){$('#overlay').hidden=true;run.pause();canvas.focus()}}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key==='Escape'&&!e.repeat&&!fullscreen.active()&&performance.now()-lastFullscreenExit>250)pause();if(e.key===' '&&!e.repeat)run.dash()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();touch={x:0,y:0};pointer.down=false;if(run.state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&run.state==='playing')pause()});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)*960/r.width;pointer.y=(e.clientY-r.top)*600/r.height});canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)*960/r.width;pointer.y=(e.clientY-r.top)*600/r.height;pointer.down=true;canvas.focus();canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>pointer.down=false);canvas.addEventListener('pointercancel',()=>pointer.down=false);
for(const button of document.querySelectorAll('[data-move]')){const direction=button.dataset.move,axis=['left','right'].includes(direction)?'x':'y',value=['left','up'].includes(direction)?-1:1;button.onpointerdown=e=>{e.preventDefault();button.setPointerCapture(e.pointerId);touch[axis]=value};button.onpointerup=button.onpointercancel=()=>touch[axis]=0}
$('#touch-dash').onpointerdown=e=>{e.preventDefault();run.dash()};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=`Son : ${sound?'on':'off'}`;$('#sound').setAttribute('aria-label',sound?'Couper le son':'Activer le son');$('#sound').setAttribute('aria-pressed',String(sound));beep()};
function frame(t){const dt=Math.min((t-last)/1000,.035);last=t;let x=(keys.has('d')?1:0)-(keys.has('q')||keys.has('a')?1:0)+touch.x,y=(keys.has('s')?1:0)-(keys.has('z')||keys.has('w')?1:0)+touch.y;const ax=(keys.has('arrowright')?1:0)-(keys.has('arrowleft')?1:0),ay=(keys.has('arrowdown')?1:0)-(keys.has('arrowup')?1:0);let aim=ax||ay?Math.atan2(ay,ax):pointer.down?Math.atan2(pointer.y-run.player.y,pointer.x-run.player.x):null;run.tick(dt,{x,y,aim,auto:matchMedia('(pointer:coarse)').matches});render(ctx,run,atlas,t/1000,assetImage);$('#health').textContent='♥ '.repeat(Math.max(0,run.player.hp))+'♡ '.repeat(run.player.maxHp-Math.max(0,run.player.hp));$('#health').setAttribute('aria-label',`${run.player.hp} points de vie sur ${run.player.maxHp}`);$('#pause-game').textContent=run.state==='paused'?'Reprendre':'Pause';$('#pause-game').disabled=!['playing','paused'].includes(run.state);$('#timer').textContent=formatTime(run.elapsed);$('#room-label').textContent=run.room.name.toUpperCase();requestAnimationFrame(frame)}
reset();requestAnimationFrame(frame);
if(assetError)toast(`Contenu indisponible : ${assetError}`);
if(selectionError)toast('Le donjon choisi est indisponible. Le donjon de test a été chargé.');
if(document.modelContext?.registerTool){const life=new AbortController();for(const tool of [{name:'read_expedition',description:'Lire l’état du donjon et de la partie en cours.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('Aucun paramètre attendu');return run.snapshot()}},{name:'start_expedition',description:'Démarrer ou recommencer le donjon affiché. Remplace la partie en cours.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('Aucun paramètre attendu');reset(true);return run.snapshot()}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
